{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Gastrodin, the closest analog, was detectable in rat brain 5 min after intravenous administration and reached peak brain concentration at 15 min, demonstrating meaningful systemic CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Salidroside crossed the blood-brain barrier after oral administration in rats, with drug detected in hippocampal tissue 3-4 hours post-dose, supporting CNS access for a closely related glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Me-4FDG, a non-natural sugar analog, did not enter the brain in human PET imaging, providing a counterexample that some glycoside-like molecules can fail to cross the BBB.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally related glycosides with direct in-vivo evidence (gastrodin, salidroside, cycasin, piceid, aucubin, kanamycin) show meaningful brain or CSF penetration after systemic administration. The negative analogs are less transferable due to probe-specific or transporter-limited behavior. Overall prediction is pass.",
  "evidence_gaps": [
    "No direct query-specific brain or CSF pharmacokinetic data are available.",
    "Analog similarities are moderate (Morgan 0.34-0.42), limiting exact transferability.",
    "Gastrodin showed a low CSF/plasma ratio in one study, and Me-4FDG/99mTc-1-TG demonstrate that not all glycoside-like molecules cross the BBB."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

